import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { useFormik } from 'formik';
import * as Yup from 'yup';

import { useAccountProfileCreateMutation, useAccountProfileRetrieveQuery } from 'entities/User';
import { useAppConfigRetrieveQuery } from 'shared/api';
import { EMainRoutes, ICurrencySettings } from 'shared/typings';
import { getApiErrors } from 'shared/utils';

const initialState: ICurrencySettings & { detail?: string } = {
	telegram: '',
	whatsapp: '',
	skype: '',
};

export const useProfileForm = () => {
	const { t } = useTranslation();
	const { data: appConfig } = useAppConfigRetrieveQuery();
	const navigate = useNavigate();
	const { data } = useAccountProfileRetrieveQuery();
	const [updateSource, { status, isLoading, error }] = useAccountProfileCreateMutation();
	const { values, errors, handleSubmit, setFieldValue, setValues, isValid, setErrors } = useFormik({
		initialValues: initialState,
		validationSchema: Yup.object({
			telegram: Yup.string().max(
				64,
				t('This field must contain no more than {{characters}} characters', { characters: 64 }),
			),
			whatsapp: Yup.string().max(
				64,
				t('This field must contain no more than {{characters}} characters', { characters: 64 }),
			),
			skype: Yup.string().max(
				64,
				t('This field must contain no more than {{characters}} characters', { characters: 64 }),
			),
		}),
		onSubmit: (values) => {
			updateSource(values);
		},
	});

	useEffect(() => {
		if (status === 'fulfilled') {
			navigate(`/${EMainRoutes.PROFILE}`);
		}
	}, [status, navigate]);

	useEffect(() => {
		if (data) {
			setValues({
				telegram: data.telegram || '',
				whatsapp: data.whatsapp || '',
				skype: data.skype || '',
			});
		}
	}, [data, setValues]);

	useEffect(() => {
		if (error) setErrors(getApiErrors(error));
	}, [error, setErrors]);

	return {
		t,
		navigate,
		isLoading,
		values,
		handleSubmit,
		errors,
		setFieldValue,
		isValid,
		appConfig,
	};
};
