import type { PayloadAction } from '@reduxjs/toolkit';
import { createSlice } from '@reduxjs/toolkit';

import { offerApi, OfferRead, OffersListApiResponse } from 'entities/Offer';

export interface OfferListState {
	offers: OfferRead[] | null;
}

export const offerListSlice = createSlice({
	name: 'offerList',
	initialState: {
		offers: null,
	} as OfferListState,
	reducers: {},
	extraReducers: (builder) => {
		builder.addMatcher(
			offerApi.endpoints?.offersList.matchFulfilled,
			(state, action: PayloadAction<OffersListApiResponse>) => {
				state.offers = action.payload.results;
			},
		);
	},
});

export default offerListSlice.reducer;
