import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import { useAccountProfileRetrieveQuery } from '../../api/api';

import styles from './PersonalManager.module.scss';

interface IPersonalManagerProps extends HTMLAttributes<HTMLDivElement> {}

export const PersonalManager: FC<IPersonalManagerProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { data } = useAccountProfileRetrieveQuery();

	if (!data?.account_manager) {
		return null;
	}

	const {
		account_manager: { first_name, last_name, email },
	} = data;

	return (
		<div {...props} className={cn(className, styles.main)}>
			<Typography.Text>{t('Your personal manager')}</Typography.Text>
			{!!(first_name || last_name) && (
				<Typography.Title level={5}>
					{first_name} {last_name}
				</Typography.Title>
			)}

			{!!email && <Typography.Text className={styles.email}>{email}</Typography.Text>}
		</div>
	);
};
