import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { OfferRead } from 'entities/Offer';

import { EJoinStates, joinOfferState, TSourceItem, TSourceOption } from './types';

const initialState: joinOfferState = {
	modalIsOpened: false,
	offer: null,
	state: EJoinStates.SOURCES,
	specifiedSource: null,
	sourceOptions: [],
	selectedSources: [],
	isInitState: true,
	isNothingToSelect: false,
};

export const joinOfferSlice = createSlice({
	name: 'joinOffer',
	initialState,
	reducers: {
		setModalState: (state, action: PayloadAction<EJoinStates.SOURCES | EJoinStates.RULES>) => {
			state.state = action.payload;
		},
		setSourceOptions: (state, action: PayloadAction<TSourceOption[]>) => {
			state.sourceOptions = action.payload;
		},
		setSelectedSources: (state, action: PayloadAction<TSourceItem[]>) => {
			state.selectedSources = action.payload;
		},
		setInitState: (state, action: PayloadAction<boolean>) => {
			state.isInitState = action.payload;
		},
		setNothingToSelect: (state, action: PayloadAction<boolean>) => {
			state.isNothingToSelect = action.payload;
		},
		closeJoinModal: (state) => ({ ...initialState, ...{ specifiedSource: state.specifiedSource } }),
		openJoinModal: (state, action: PayloadAction<OfferRead>) => {
			state.modalIsOpened = true;
			state.offer = action.payload;
		},
	},
});

export default joinOfferSlice.reducer;
export const {
	setModalState,
	openJoinModal,
	setSourceOptions,
	setSelectedSources,
	setInitState,
	setNothingToSelect,
	closeJoinModal,
} = joinOfferSlice.actions;
