import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { Source } from 'entities/Source';
import { INITIAL_SOURCE_FORM_STATE } from 'widgets/SourceForm';

import { EOnboardingStates, EOnboardingSteps, onboardingState } from './types';

const initialState: onboardingState = {
	modalIsOpened: false,
	state: EOnboardingStates.WELCOME,
	step: EOnboardingSteps.FIRST,
	fullyCompleted: false,
	sourceForm: INITIAL_SOURCE_FORM_STATE,
};

export const onboardingSlice = createSlice({
	name: 'onboarding',
	initialState,
	reducers: {
		setModalState: (state, action: PayloadAction<EOnboardingStates>) => {
			state.state = action.payload;
		},
		setStep: (state, action: PayloadAction<EOnboardingSteps>) => {
			state.step = action.payload;
		},
		setThirdStateComplete: (state) => {
			state.fullyCompleted = true;
			state.state = EOnboardingStates.FINAL;
		},
		setSourceForm: (state, action: PayloadAction<Source>) => {
			state.sourceForm = action.payload;
		},
		closeOnboardingModal: () => initialState,
		openOnboardingModal: (state) => {
			state.modalIsOpened = true;
		},
	},
});

export default onboardingSlice.reducer;
export const {
	setModalState,
	setStep,
	openOnboardingModal,
	setThirdStateComplete,
	closeOnboardingModal,
	setSourceForm,
} = onboardingSlice.actions;
