import { FetchBaseQueryError } from '@reduxjs/toolkit/query';

type ErrorValue = string | Record<string, unknown>;

export const getApiErrors = (error: unknown): Record<string, ErrorValue> => {
	if ((error as FetchBaseQueryError)?.status === 400) {
		const errorData = (error as FetchBaseQueryError).data as Record<string, unknown>;
		return processErrors(errorData);
	}
	return {};
};

const processErrors = (obj: Record<string, unknown>): Record<string, ErrorValue> => {
	const result: Record<string, ErrorValue> = {};

	Object.entries(obj).forEach(([key, value]) => {
		if (Array.isArray(value)) {
			result[key] = value.join(', ');
		} else if (typeof value === 'object' && value !== null) {
			result[key] = processErrors(value as Record<string, unknown>);
		}
	});

	return result;
};
