import { useEffect, useRef, useState } from 'react';
import { useSearchParams } from 'react-router-dom';

import dayjs from 'dayjs';

import { EFilters } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';

import 'dayjs/locale/ru';

dayjs.locale('ru');

const filterFormatDate = 'YYYY-MM-DDTHH:mm:ss.SSS[Z]';
const getStartOfDay: (date: dayjs.Dayjs) => string = (date: dayjs.Dayjs) =>
	date.startOf('day').utc().format(filterFormatDate);
const getEndOfDay: (date: dayjs.Dayjs) => string = (date: dayjs.Dayjs) =>
	date.endOf('day').utc().format(filterFormatDate);

export const useDateFilters = (after: EFilters, before: EFilters) => {
	const [searchParams, setSearchParams] = useSearchParams();
	const setSearchParamsRef = useRef(setSearchParams); // ref to store the actual setSearchParams
	setSearchParamsRef.current = setSearchParams; // Update ref on every change setSearchParams

	const dateFilterChange = (fields: EFilters[], values: string[]) => {
		const newSearchParams = new URLSearchParams(searchParams.toString());
		fields.forEach((field, index) => {
			if (values[index]) {
				newSearchParams.set(field, values[index]);
			} else {
				newSearchParams.delete(field);
			}
		});
		newSearchParams.delete(EPaginationParams.OFFSET);
		setSearchParamsRef.current(newSearchParams);
	};

	const [dateRange, setDateRange] = useState<[dayjs.Dayjs | null, dayjs.Dayjs | null]>();

	useEffect(() => {
		const newBeforeValue = searchParams.has(before) ? dayjs(searchParams.get(before)).startOf('day') : null;
		const newAfterValue = searchParams.has(after) ? dayjs(searchParams.get(after)).startOf('day') : null;
		setDateRange([newAfterValue, newBeforeValue]);
	}, [after, before, searchParams]);

	return {
		dateRange,
		onDateChange: (dates: [dayjs.Dayjs | null, dayjs.Dayjs | null] | null) => {
			if (dates) {
				const [start, end] = dates;
				const fromDate = start ? getStartOfDay(start) : '';
				const toDate = end ? getEndOfDay(end) : '';
				dateFilterChange([after, before], [fromDate, toDate]);
			} else {
				dateFilterChange([after, before], ['', '']);
			}
		},
	};
};
