import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';

import { useAccountProfileRetrieveQuery } from '../../api/api';
import styles from '../AccountSett/AccountSett.module.scss';

interface IPersonalInfoProps extends HTMLAttributes<HTMLDivElement> {}

export const PersonalInfo: FC<IPersonalInfoProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { data } = useAccountProfileRetrieveQuery();

	return (
		<div {...props} className={cn(className, styles.table)}>
			<div className={styles.header}>
				<Typography.Title level={5} type="secondary">
					{t('Personal information')}
				</Typography.Title>
				<ButtonStyleLink type="link" to={`/${EMainRoutes.PROFILE}/${EMainRoutes.EDIT}`}>
					{t('Edit')}
				</ButtonStyleLink>
			</div>
			<dl className={styles.body}>
				<dt className={styles.dt}>
					<Typography.Text type="secondary">{t('Telegram account')}</Typography.Text>
				</dt>
				<dd className={styles.dd}>
					<Typography.Text>{data?.telegram || t('None')}</Typography.Text>
				</dd>
				<dt className={styles.dt}>
					<Typography.Text type="secondary">{t('WhatsApp')}</Typography.Text>
				</dt>
				<dd className={styles.dd}>
					<Typography.Text>{data?.whatsapp || t('None')}</Typography.Text>
				</dd>
				<dt className={cn(styles.dt, styles.dt_last)}>
					<Typography.Text type="secondary">{t('Skype account')}</Typography.Text>
				</dt>
				<dd className={cn(styles.dd, styles.dd_last)}>
					<Typography.Text>{data?.skype || t('None')}</Typography.Text>
				</dd>
			</dl>
		</div>
	);
};
