import { FC, HTMLAttributes } from 'react';

import { DatePicker } from 'antd';
import cn from 'classnames';

import { EFilters } from 'features/Filters/model/enums';

import { useDateFilters } from '../../hooks/useDateFilters';

import styles from './TransactionsFilters.module.scss';

const { RangePicker } = DatePicker;

interface ITransactionsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const TransactionsFilters: FC<ITransactionsFiltersProps> = ({ className, ...props }) => {
	const { dateRange, onDateChange } = useDateFilters(EFilters.DATE_FROM, EFilters.DATE_TO);

	return (
		<div {...props} className={cn(className, styles.transactionsFilters)}>
			<RangePicker value={dateRange} onChange={onDateChange} size="large" format="YYYY-MM-DD" />
		</div>
	);
};
