import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import i18n from 'i18next';
import { useCommonSlice } from 'shared/hooks';
import { EGaCategories, EGaEvents, EGaTypes, ELanguages } from 'shared/typings';
import { sendGaEvent } from 'shared/utils';

import { useAccountLanguageCreateMutation } from '../api/api';
import { LanguageEnum } from '../api/codegen.api';

export const useChangeLanguage = () => {
	const { t } = useTranslation();
	const [updateLanguage] = useAccountLanguageCreateMutation();
	const [lang, setLang] = useState(ELanguages.EN);
	const { language } = useCommonSlice();
	const handleLangChange = (value: string | null) => {
		updateLanguage({ language: value as LanguageEnum });
		sendGaEvent(EGaEvents.CLICK_SELECT_LANGUAGE, {
			event_option1: EGaCategories.ACCOUNT,
			event_option2: EGaTypes.FOOTER,
			event_option4: value as string,
		});
		i18n.changeLanguage(language);
		location.reload();
	};

	useEffect(() => {
		setLang(language);
		i18n.changeLanguage(language);
	}, [language]);

	return {
		t,
		lang,
		setLang,
		handleLangChange,
	};
};
