import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, DatePicker, Select } from 'antd';
import cn from 'classnames';
import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';

import { useDateFilters } from 'features/Filters/hooks/useDateFilters';
import { EFilters } from 'features/Filters/model/enums';
import { MONTHS_OPTIONS } from 'shared/consts';

import { useFilters } from '../../hooks/useFilters';
import { getYearsList } from '../../utils/getYearsList';
import { prepareDate } from '../../utils/prepareDate';

import styles from './ReportsPeriodFilters.module.scss';

dayjs.extend(utc);

const { RangePicker } = DatePicker;

interface IReportsPeriodFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsPeriodFilters: FC<IReportsPeriodFiltersProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue } = useFilters(true);
	const { dateRange, onDateChange } = useDateFilters(EFilters.ACTION_DATE_FROM, EFilters.ACTION_DATE_TO);

	const setPeriod = (diff: number = 0) => {
		const endDate = dayjs(prepareDate(new Date()));
		const startDate = dayjs(prepareDate(new Date(), diff));
		onDateChange([startDate, endDate]);
	};

	const periodIsActive = (diff: number = 0) =>
		getFilterValue(EFilters.ACTION_DATE_FROM) ===
			dayjs(prepareDate(new Date(), diff)).startOf('day').utc().format('YYYY-MM-DDTHH:mm:ss.SSS[Z]') &&
		getFilterValue(EFilters.ACTION_DATE_TO) ===
			dayjs(prepareDate(new Date())).endOf('day').utc().format('YYYY-MM-DDTHH:mm:ss.SSS[Z]');

	const setMonth = (diff: number = 0) => {
		const today = dayjs();
		const targetDate = diff === 0 ? today : today.subtract(1, 'month');

		const endDate = targetDate.endOf('month');
		const startDate = targetDate.startOf('month');
		onDateChange([startDate, endDate]);
	};

	const onYearChange = (year: string) => {
		const date = getFilterValue(EFilters.ACTION_DATE_FROM) ? dayjs(getFilterValue(EFilters.ACTION_DATE_FROM)) : dayjs();

		const targetDate = date.year(parseInt(year));

		onDateChange([targetDate.startOf('year'), targetDate.endOf('year')]);
	};

	const onMonthChange = (month: string) => {
		const date = getFilterValue(EFilters.ACTION_DATE_FROM) ? dayjs(getFilterValue(EFilters.ACTION_DATE_FROM)) : dayjs();

		const targetDate = date.month(parseInt(month) - 1);

		onDateChange([targetDate.startOf('month'), targetDate.endOf('month')]);
	};

	const monthIsActive = (diff: number = 0) => {
		const today = dayjs();
		const targetDate = diff === 0 ? today : today.subtract(1, 'month');

		return (
			getFilterValue(EFilters.ACTION_DATE_FROM) ===
				targetDate.startOf('month').startOf('day').utc().format('YYYY-MM-DDTHH:mm:ss.SSS[Z]') &&
			getFilterValue(EFilters.ACTION_DATE_TO) ===
				targetDate.endOf('month').endOf('day').utc().format('YYYY-MM-DDTHH:mm:ss.SSS[Z]')
		);
	};

	return (
		<div {...props} className={cn(className, styles.filters)}>
			<Button type={periodIsActive(0) ? 'primary' : 'default'} size="large" onClick={() => setPeriod(0)}>
				{t('Today')}
			</Button>
			<Button type={periodIsActive(7) ? 'primary' : 'default'} size="large" onClick={() => setPeriod(7)}>
				{t('Last 7 days')}
			</Button>
			<Button type={periodIsActive(30) ? 'primary' : 'default'} size="large" onClick={() => setPeriod(30)}>
				{t('Last 30 days')}
			</Button>
			<Button type={monthIsActive(-1) ? 'primary' : 'default'} size="large" onClick={() => setMonth(-1)}>
				{t('Last month')}
			</Button>
			<Button type={monthIsActive(0) ? 'primary' : 'default'} size="large" onClick={() => setMonth(0)}>
				{t('This month')}
			</Button>
			<Select
				className={styles.year}
				value={
					getFilterValue(EFilters.ACTION_DATE_FROM)
						? dayjs(getFilterValue(EFilters.ACTION_DATE_FROM)).format('YYYY')
						: dayjs().format('YYYY')
				}
				options={getYearsList()}
				onChange={onYearChange}
				placeholder={t('Year')}
				size="large"
			/>
			<Select
				className={styles.month}
				value={
					getFilterValue(EFilters.ACTION_DATE_FROM)
						? (dayjs(getFilterValue(EFilters.ACTION_DATE_FROM)).month() + 1).toString()
						: (dayjs().month() + 1).toString()
				}
				options={MONTHS_OPTIONS}
				onChange={onMonthChange}
				placeholder={t('Month')}
				size="large"
			/>
			<RangePicker className={styles.date} value={dateRange} onChange={onDateChange} size="large" format="YYYY-MM-DD" />
		</div>
	);
};
