import { FC, HTMLAttributes, ReactNode } from 'react';

import { Tooltip as AntTooltip } from 'antd';
import type { TooltipPlacement } from 'antd/es/tooltip';
import cn from 'classnames';

import InfoIcon from 'assets/images/info.svg?react';

import styles from './InfoTooltip.module.scss';

interface IInfoTooltipProps extends HTMLAttributes<HTMLDivElement> {
	size?: 's' | 'm' | 'l' | 'xl' | 'xxl';
	text: ReactNode;
	place?: TooltipPlacement;
}

export const InfoTooltip: FC<IInfoTooltipProps> = ({ className, place = 'top', size = 'l', text, ...props }) => {
	return (
		<AntTooltip
			{...props}
			className={cn(className, 'tooltip')}
			placement={place}
			title={text}
			styles={{ root: { zIndex: 1000 } }}>
			<InfoIcon className={cn(styles.infoTooltipIcon, styles[`infoTooltipIcon_size_${size}`])} />
		</AntTooltip>
	);
};
