import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import { Source } from 'entities/Source';
import { EInternalEmails } from 'shared/typings';
import { Faq, IFaqItem } from 'shared/ui';
import { SourceForm } from 'widgets/SourceForm';

import styles from './CreateSourceLayout.module.scss';

interface ICreateSourceLayoutProps extends HTMLAttributes<HTMLDivElement> {
	initialState: Source;
	isEditing?: boolean;
	isFetching?: boolean;
	sourceUuid?: string;
}

export const CreateSourceLayout: FC<ICreateSourceLayoutProps> = ({
	className,
	initialState,
	isEditing,
	isFetching,
	sourceUuid,
	...props
}) => {
	const { t } = useTranslation();

	const faqItems = [
		{
			title: t('How does it work?'),
			text: t('A short description of how the form works'),
			size: 'm',
		},
		{
			title: t('Source'),
			text: t('The AppsFlyer source is the Media source PID. Example: networkx_int.'),
		},
		// {
		//   title: t('Types of traffic'),
		//   text: t('A short note on how to choose a Types of traffic'),
		// },
	];

	return (
		<div {...props} className={cn(className, styles.createSource)}>
			<SourceForm
				initialState={initialState}
				isEditing={isEditing}
				className={styles.form}
				isFetching={isFetching}
				sourceUuid={sourceUuid}
			/>

			<div className={styles.info}>
				<Faq items={faqItems as IFaqItem[]} />
				<Typography.Link href={`mailto:${EInternalEmails.SUPPORT}`}>{t('Need help?')}</Typography.Link>
			</div>
		</div>
	);
};
